```go
package main

import (
	"database/sql"
	"fmt"
)

type User struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// ListUsers retrieves users sorted by the specified column and direction.
func ListUsers(db *sql.DB, sortColumn string, sortDirection string) ([]User, error) {
	// Whitelist allowed sort columns
	allowedColumns := map[string]bool{
		"id":    true,
		"name":  true,
		"email": true,
	}

	if !allowedColumns[sortColumn] {
		return nil, fmt.Errorf("invalid sort column: %s", sortColumn)
	}

	query := fmt.Sprintf("SELECT id, name, email FROM users ORDER BY %s %s", sortColumn, sortDirection)

	rows, err := db.Query(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var users []User
	for rows.Next() {
		var u User
		if err := rows.Scan(&u.ID, &u.Name, &u.Email); err != nil {
			return nil, err
		}
		users = append(users, u)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return users, nil
}
```

